// Built-in Edge v6 tag classifications. See docs/adr/0002-tag-taxonomy.md.

export const BLOCK_TAGS = new Set([
  'if',
  'unless',
  'each',
  'component',
  'slot',
  'pushTo',
  'pushOnceTo',
  'pushToTop',
  'pushOnceToTop',
  'inputError',
  'can',
  'cannot',
  'error',
])

export const BRANCH_TAGS = new Set(['else', 'elseif'])

export const INLINE_TAGS = new Set([
  'let',
  'assign',
  'include',
  'includeIf',
  'inject',
  'eval',
  'stack',
  'markdown',
  'newError',
  'svg',
  'markdownSlot',
  // Common AdonisJS plugin tags. Author writes `@vite(...)`,
  // `@flashMessage(...)` etc. without `@end`. See ADR-0002 for the policy
  // on adding new ones.
  'vite',
  'flashMessage',
  'flashMessages',
  'dd',
  'dump',
  'viteReactRefresh',
])

export const CLOSER = 'end'

export function isKnownTag(name) {
  return BLOCK_TAGS.has(name) || BRANCH_TAGS.has(name) || INLINE_TAGS.has(name) || name === CLOSER
}
